using System;
using System.Collections.Generic;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Panels")]
    public interface IPanelPack : IBettaCollection
    {
        [GrasshopperMethod("Panel Grid", "Divide a surface into four-sided panels and check how flat they are")]
        (List<Polyline> Panels, List<double> Areas, List<double> Deviation, List<int> NonPlanar) PanelGrid(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 10)] int vCount,
            [GrasshopperParameter("Inset", DefaultValue = 0.0)] double inset,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.01)] double tolerance);
    }

    public class PanelPack : IPanelPack
    {
        public (List<Polyline> Panels, List<double> Areas, List<double> Deviation, List<int> NonPlanar) PanelGrid(
            Surface surface, int uCount, int vCount, double inset, double tolerance)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface), "Surface is required.");
            if (uCount < 1 || vCount < 1) throw new ArgumentException("U Count and V Count must be at least 1.");
            if (inset < 0) throw new ArgumentException("Inset must not be negative.");
            if (tolerance < 0) throw new ArgumentException("Tolerance must not be negative.");

            var panels = new List<Polyline>();
            var areas = new List<double>();
            var deviation = new List<double>();
            var nonPlanar = new List<int>();

            var du = surface.Domain(0);
            var dv = surface.Domain(1);

            for (int i = 0; i < uCount; i++)
            {
                double u0 = du.ParameterAt(i / (double)uCount);
                double u1 = du.ParameterAt((i + 1) / (double)uCount);
                for (int j = 0; j < vCount; j++)
                {
                    double v0 = dv.ParameterAt(j / (double)vCount);
                    double v1 = dv.ParameterAt((j + 1) / (double)vCount);

                    var c = new[]
                    {
                        surface.PointAt(u0, v0),
                        surface.PointAt(u1, v0),
                        surface.PointAt(u1, v1),
                        surface.PointAt(u0, v1),
                    };

                    if (inset > 0)
                    {
                        var avg = new Point3d(
                            (c[0].X + c[1].X + c[2].X + c[3].X) / 4,
                            (c[0].Y + c[1].Y + c[2].Y + c[3].Y) / 4,
                            (c[0].Z + c[1].Z + c[2].Z + c[3].Z) / 4);
                        for (int k = 0; k < 4; k++)
                        {
                            var toCenter = avg - c[k];
                            double len = toCenter.Length;
                            if (len > 0) c[k] += toCenter * (Math.Min(inset, len) / len);
                        }
                    }

                    var polyline = new Polyline(new[] { c[0], c[1], c[2], c[3], c[0] });
                    double area = 0.5 * (Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]).Length
                                       + Vector3d.CrossProduct(c[2] - c[0], c[3] - c[0]).Length);

                    var normal = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]);
                    double nLen = normal.Length;
                    double dev = nLen > 0 ? Math.Abs(normal * (c[3] - c[0])) / nLen : 0;

                    if (dev > tolerance) nonPlanar.Add(panels.Count);
                    panels.Add(polyline);
                    areas.Add(area);
                    deviation.Add(dev);
                }
            }

            return (panels, areas, deviation, nonPlanar);
        }
    }
}
